// Regenerate lib/editor/flatten-iife.generated.ts from lib/editor/flatten.ts.
//
// The deck-snapshot-bake Inngest function runs `flattenSlideSection` INSIDE a
// puppeteer page (it needs getComputedStyle + live layout), so it needs the
// flattener as a browser-executable IIFE string. flatten.ts stays the single
// source of truth; this bundles it (types stripped, its one internal import
// inlined) into a committed constant so runtime depends on NO bundler.
//
// ‼️ Re-run after editing lib/editor/flatten.ts or lib/editor/leaves.ts:
//   node scripts/gen-flatten-bundle.mjs
//
// esbuild is resolved via `npx` (transitively present); no package dep added.

import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const code = execFileSync(
  "npx",
  ["esbuild", "lib/editor/flatten.ts", "--bundle", "--format=iife", "--global-name=TQFlatten"],
  { encoding: "utf8", maxBuffer: 32 * 1024 * 1024 },
);

const out = `// @generated by scripts/gen-flatten-bundle.mjs from lib/editor/flatten.ts — DO NOT EDIT.
// Browser-executable IIFE of the flattener, injected into the puppeteer page by
// the deck-snapshot-bake function. Re-run the generator after changing flatten.ts.
// Exposes a global \`TQFlatten\` with \`flattenSlideSection\` and \`flattenSkipReason\`.

export const FLATTEN_IIFE = ${JSON.stringify(code)};
`;

writeFileSync("lib/editor/flatten-iife.generated.ts", out);
console.log(`wrote lib/editor/flatten-iife.generated.ts (${code.length} bytes of bundle)`);
